programs = {
  hyprlock = lib.optionalAttrs (!isDarwin && isDesktop) {
    enable = true;
    # withHostNss: hyprlock runs under nix glibc, whose NSS can't load the host
    # libnss_systemd.so.2, so getpwuid fails for a systemd-userdb user (sauyon,
    # uid 60006, not in /etc/passwd). hyprlock then has no username to hand PAM
    # and silently rejects EVERY password (fingerprint uses a separate path,
    # masking it). Wrap NSS *outside* nixGL so the LD_LIBRARY_PATH prefix
    # propagates through to the real binary.
    package = withHostNss (config.lib.nixGL.wrap pkgs.hyprlock);
    settings = {
      general = {
        hide_cursor = true;
      };

      background = [
        {
          monitor = "";
          # path = "screenshot";   # disabled to debug deadlock
          blur_passes = 3;
          blur_size = 8;
        }
      ];

      auth = {
        pam.module = "login";
        fingerprint.enabled = true;
      };

      input-field = [
        {
          monitor = "";
          size = "300, 50";
          position = "0, -80";
          halign = "center";
          valign = "center";
          outline_thickness = 2;
          dots_size = 0.33;
          dots_spacing = 0.15;
          dots_center = true;
          outer_color = "rgb(151515)";
          inner_color = "rgb(200, 200, 200)";
          font_color = "rgb(10, 10, 10)";
          fade_on_empty = true;
          placeholder_text = "<i>Password...</i>";
          hide_input = false;
          check_color = "rgb(204, 136, 34)";
          fail_color = "rgb(204, 34, 34)";
          fail_text = "<i>$FAIL <b>($ATTEMPTS)</b></i>";
          capslock_color = "rgb(170, 0, 255)";
        }
      ];

      label = [
        {
          monitor = "";
          text = ''cmd[update:1000] echo "$(date +"%H:%M:%S")"'';
          font_size = 64;
          font_family = "NotoSans Nerd Font";
          position = "0, 80";
          halign = "center";
          valign = "center";
          color = "rgba(255, 255, 255, 0.9)";
        }
        {
          monitor = "";
          text = ''cmd[update:60000] echo "$(date +"%A, %B %-d")"'';
          font_size = 24;
          font_family = "NotoSans Nerd Font";
          position = "0, 10";
          halign = "center";
          valign = "center";
          color = "rgba(255, 255, 255, 0.7)";
        }
        {
          monitor = "";
          text = " $FPRINTPROMPT";
          font_size = 14;
          font_family = "NotoSans Nerd Font";
          position = "0, -140";
          halign = "center";
          valign = "center";
          color = "rgba(255, 255, 255, 0.7)";
        }
      ];
    };
  };
  waybar = let
    fontSize = hidpi.waybarFontSize;
    barHeight = hidpi.waybarBarHeight;
    shared = {
      layer = "top";
      position = "top";
      height = barHeight;
      spacing = 0;

      "hyprland/workspaces" = {
        format = "{id}";
        on-click = "activate";
        sort-by-number = true;
      };
      "hyprland/window" = {
        format = "{title}";
        max-length = 60;
        separate-outputs = true;
      };
      mpris = {
        format = "{player_icon} {dynamic}";
        format-paused = "{status_icon} {dynamic}";
        player-icons.default = "";
        status-icons.paused = "";
        dynamic-len = 40;
      };
      wireplumber = {
        format = "{icon} {volume}%";
        format-muted = "󰝟";
        format-icons = [ "" "" "" ];
        on-click = "${pkgs.pwvucontrol}/bin/pwvucontrol";
        scroll-step = 5;
      };
      network = {
        format-wifi = "  {essid}";
        format-ethernet = " {ifname}";
        format-disconnected = "󰖪 offline";
        tooltip-format = "{ifname}: {ipaddr}";
        max-length = 30;
        on-click = "ghostty -e nmtui";
      };
      bluetooth = {
        format = " {status}";
        format-disabled = "󰂲";
        format-connected = " {device_alias}";
        format-connected-battery = " {device_alias} {device_battery_percentage}%";
        tooltip-format = "{controller_alias}\n{num_connections} connected";
      };
      tray = {
        spacing = 8;
        icon-size = 18;
      };
      memory = {
        format = "󰍛 {percentage}%";
        interval = 2;
      };
      battery = {
        states = { warning = 30; critical = 15; };
        format = "{icon} {capacity}%";
        format-charging = "󰂄 {capacity}% (+{time})";
        format-discharging = "{icon} {capacity}% (-{time})";
        format-plugged = "󰚥 {capacity}%";
        format-full = "󰁹 {capacity}%";
        format-time = "{H}:{M:02}";
        format-icons = [ "" "" "" "" "" ];
      };
      clock = {
        format = "{:%a %m-%d %H:%M:%S}";
        interval = 1;
        tooltip-format = "<tt>{calendar}</tt>";
      };
      "custom/notifications" = {
        exec = ''makoctl mode | grep -qx do-not-disturb && echo '{"text":"󰂛","class":"dnd"}' || echo '{"text":"󰂚"}' '';
        return-type = "json";
        interval = 2;
        on-click = "makoctl dismiss --all";
        on-click-right = "makoctl mode -t do-not-disturb";
      };
      "custom/caffeine" = {
        exec = "${caffeine}/bin/caffeine waybar";
        return-type = "json";
        interval = 5;

toolUseResult.stdout:
    };
  };
};

